const sections=["work","process","skills","writing","journey","contact"];
let language="vi",currentMetric="clicks",currentSkill=0,manualSkill=false,skillTimer=null,skillVisible=false,skillHover=false,skillFocus=false,menuOpen=false;
const reduced=window.matchMedia("(prefers-reduced-motion: reduce)");
const $=selector=>document.querySelector(selector);
const $$=selector=>Array.from(document.querySelectorAll(selector));
function formatMetric(value,unit){
  const locale=language==="vi"?"vi-VN":"en-US";
  if(unit==="integer")return new Intl.NumberFormat(locale).format(value);
  if(unit==="percent")return new Intl.NumberFormat(locale,{minimumFractionDigits:2,maximumFractionDigits:2}).format(value)+"%";
  return new Intl.NumberFormat(locale,{minimumFractionDigits:1,maximumFractionDigits:1}).format(value);
}
function renderMetric(){
  const item=metricData[currentMetric];
  $("#metric-title").textContent=item.title[language];
  $("#metric-before").textContent=formatMetric(item.before,item.unit);
  $("#metric-after").textContent=formatMetric(item.after,item.unit);
  $("#meter-before").style.width=item.beforeWidth+"%";
  $("#meter-after").style.width=item.afterWidth+"%";
  $("#metric-reading").textContent=item.reading[language];
  $$("[data-metric]").forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.metric===currentMetric)));
}
function positionIndicator(){
  const nav=$("#desktop-nav"),active=nav.querySelector('a[aria-current="location"]'),indicator=nav.querySelector(".nav-indicator");
  if(!active){indicator.style.width="0";return}
  const a=active.getBoundingClientRect(),n=nav.getBoundingClientRect();
  indicator.style.width=a.width+"px";indicator.style.transform="translateX("+(a.left-n.left)+"px)";
}
function setActiveSection(id){
  $$("#desktop-nav a").forEach(link=>link.getAttribute("href")==="#"+id?link.setAttribute("aria-current","location"):link.removeAttribute("aria-current"));
  positionIndicator();
}
function setLanguage(next){
  if(!copy[next])return;
  language=next;
  document.documentElement.lang=next;
  document.title=next==="vi"?"Phạm Tiến Đạt — SEO Executive":"Dat Pham — SEO Executive";
  $('meta[name="description"]').content=next==="vi"?"Phạm Tiến Đạt — SEO Executive. Tư duy về search intent, nội dung, dữ liệu GSC và các bài viết đã xuất bản.":"Dat Pham — SEO Executive. Search intent, content, GSC evidence and published writing.";
  $$("[data-i18n]").forEach(element=>{const value=copy[next][element.dataset.i18n];if(value!==undefined)element.textContent=value});
  $$("[data-lang]").forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.lang===next)));
  $("#menu-toggle").setAttribute("aria-label",copy[next][menuOpen?"menuClose":"menuOpen"]);
  $(".brand").setAttribute("aria-label",(next==="vi"?"Phạm Tiến Đạt — đầu trang":"Dat Pham — home"));
  $(".insight-row").setAttribute("aria-label",(next==="vi"?"Các câu hỏi trong công việc SEO":"Questions I ask in SEO work"));
  $(".signal-lab").setAttribute("aria-label",copy[next].signalAria);
  $("#desktop-nav").setAttribute("aria-label",copy[next].navigation);
  $("#mobile-nav").setAttribute("aria-label",copy[next].mobileNavigation);
  $(".metric-picker").setAttribute("aria-label",copy[next].metricsLabel);
  $("#compare-slider").setAttribute("aria-label",copy[next].compareSlider);
  updateComparison();
  $(".skill-tabs").setAttribute("aria-label",copy[next].skillsTablist);
  $("#rail-prev").setAttribute("aria-label",copy[next].railPrev);
  $("#rail-next").setAttribute("aria-label",copy[next].railNext);
  $$("[data-value]").forEach(element=>element.textContent=formatMetric(Number(element.dataset.value),"integer"));
  $$("[data-percent]").forEach(element=>element.textContent=formatMetric(Number(element.dataset.percent),"percent"));
  $$("[data-decimal]").forEach(element=>element.textContent=formatMetric(Number(element.dataset.decimal),"decimal"));
  $(".case-figure strong").innerHTML=(next==="vi"?"+27,1":"+27.1")+"<span>%</span>";
  renderMetric();
  requestAnimationFrame(positionIndicator);
  try{localStorage.setItem("dat-seo-language",next)}catch{}
}
function closeMenu(returnFocus=false){
  if(!menuOpen)return;
  menuOpen=false;document.body.classList.remove("menu-open");$("#menu-toggle").setAttribute("aria-expanded","false");$("#menu-toggle").setAttribute("aria-label",copy[language].menuOpen);$("#mobile-nav").inert=true;$("#menu-backdrop").hidden=true;
  if(returnFocus)$("#menu-toggle").focus();
}
function openMenu(){
  if(menuOpen)return;
  menuOpen=true;document.body.classList.add("menu-open");$("#menu-toggle").setAttribute("aria-expanded","true");$("#menu-toggle").setAttribute("aria-label",copy[language].menuClose);$("#mobile-nav").inert=false;$("#menu-backdrop").hidden=false;
  const focusFirst=()=>{if(menuOpen)$("#mobile-nav a").focus()};
  requestAnimationFrame(focusFirst);
  setTimeout(focusFirst,reduced.matches?0:380);
}
function activateSkill(index,user=false){
  const tabs=$$("[data-skill]"),panels=$$(".skill-panels [role=tabpanel]");
  currentSkill=(index+tabs.length)%tabs.length;
  tabs.forEach((tab,i)=>{tab.setAttribute("aria-selected",String(i===currentSkill));tab.tabIndex=i===currentSkill?0:-1});
  panels.forEach((panel,i)=>panel.hidden=i!==currentSkill);
  if(user){manualSkill=true;stopSkillTimer()}
  else scheduleSkillTimer();
}
function stopSkillTimer(){clearTimeout(skillTimer);skillTimer=null;$(".skill-tabs").classList.remove("is-autoplay")}
function canAutoSkill(){return skillVisible&&!skillHover&&!skillFocus&&!manualSkill&&!reduced.matches&&document.visibilityState==="visible"}
function scheduleSkillTimer(){
  stopSkillTimer();
  if(!canAutoSkill())return;
  void $(".skill-tabs").offsetWidth;
  $(".skill-tabs").classList.add("is-autoplay");
  skillTimer=setTimeout(()=>activateSkill(currentSkill+1),7000);
}
function updateRail(){
  const rail=$("#article-rail"),cards=$$(".article-card");
  const nearest=cards.reduce((best,card,index)=>Math.abs(card.offsetLeft-rail.offsetLeft-rail.scrollLeft)<Math.abs(cards[best].offsetLeft-rail.offsetLeft-rail.scrollLeft)?index:best,0);
  $("#rail-status").textContent=(nearest+1)+" / "+cards.length;
  $("#rail-prev").disabled=rail.scrollLeft<5;
  $("#rail-next").disabled=rail.scrollLeft>=rail.scrollWidth-rail.clientWidth-5;
}
function moveRail(direction){
  const rail=$("#article-rail"),card=$(".article-card"),gap=parseFloat(getComputedStyle(rail).gap)||0;
  rail.scrollBy({left:direction*(card.getBoundingClientRect().width+gap),behavior:reduced.matches?"instant":"smooth"});
}
function updateComparison(){
  const slider=$("#compare-slider"),value=Number(slider.value);
  $("#compare-wipe").style.setProperty("--split",value+"%");
  slider.setAttribute("aria-valuetext",language==="vi"?(100-value)+"% kỳ trước, "+value+"% kỳ sau":(100-value)+"% earlier period, "+value+"% later period");
}
$$("[data-lang]").forEach(button=>button.addEventListener("click",()=>setLanguage(button.dataset.lang)));
